import type { CategoryNode } from "../types";

/**
 * Build columns for category picker: root categories + each level of path children.
 */
export function buildCategoryColumns(
  categories: CategoryNode[],
  categoryPath: CategoryNode[],
): CategoryNode[][] {
  const cols: CategoryNode[][] = [];
  if (categories.length > 0) {
    cols.push(categories);
  }
  categoryPath.forEach((node) => {
    if (node.children && node.children.length > 0) {
      cols.push(node.children);
    }
  });
  return cols;
}
